          alert("Por favor ingresa ambos campos");
          return;
      }
      updateSupabaseConfig(sbUrl, sbKey);
  };

  const downloadQR = () => {
    if (!qrContainerRef.current) return;

    const canvas = qrContainerRef.current.querySelector('canvas');
    if (!canvas) {
        alert("No se encontró el código QR para descargar.");
        return;
    }

    try {
        // Intentamos generar la imagen
        const dataUrl = canvas.toDataURL("image/png");
        const link = document.createElement("a");
        link.href = dataUrl;
        link.download = `QR_Menu_Potatoes_${new Date().getTime()}.png`;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
    } catch (err) {
        console.error("Error al descargar el QR:", err);
        alert("No se pudo descargar el QR con el logo central debido a restricciones de seguridad del navegador (CORS). Intente usar el QR sin logo o contacte a soporte.");
    }
